"nodes": [
  {
    "id": "classify",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": { "label": "Classify Escalation" },
    "inputs": {
      "script": "const senderDomain = $vars.start.output.senderDomain;\nconst customerMatchStatus = $vars.start.output.customerMatchStatus;\nconst isDuplicate = $vars.start.output.isDuplicate;\nconst productionDown = $vars.start.output.productionDown;\nconst workaroundAvailable = $vars.start.output.workaroundAvailable;\n\nlet escalationPath;\nif (!senderDomain || senderDomain.trim() === '') {\n  escalationPath = 'missing_domain';\n} else if (customerMatchStatus === 'none') {\n  escalationPath = 'unknown_customer';\n} else if (customerMatchStatus === 'multiple') {\n  escalationPath = 'multiple_matches';\n} else if (isDuplicate === true) {\n  escalationPath = 'duplicate';\n} else {\n  escalationPath = 'escalation';\n}\n\nlet severity = 'informational';\nlet engineeringNeeded = false;\n\nif (escalationPath === 'escalation') {\n  if (productionDown === true && workaroundAvailable !== true) {\n    severity = 'Sev1';\n  } else if (productionDown === true && workaroundAvailable === true) {\n    severity = 'Sev2';\n  } else {\n    severity = 'Sev3';\n  }\n  engineeringNeeded = (severity === 'Sev1' || severity === 'Sev2');\n}\n\nconst responseMode = escalationPath === 'escalation' ? 'Draft' : 'None';\n\nreturn { escalationPath, severity, engineeringNeeded, responseMode };"
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the script fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "escalationDecision",
    "type": "core.logic.decision",
    "typeVersion": "1.2",
    "display": { "label": "Is Escalation?" },
    "inputs": {
      "expression": "$vars.classify.output.escalationPath === 'escalation'",
      "trueLabel": "Escalation",
      "falseLabel": "Triage"
    }
  },
  {
    "id": "slackEscalationErrorHandler",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": { "label": "Handle Escalation Slack Error" },
    "inputs": {
      "script": "const err = $vars.slackEscalationAlert1.error;\nreturn { slackMessageId: null, errorMessage: err ? err.message : 'Slack send failed' };"
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the script fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "slackTriageErrorHandler",
    "type": "core.action.script",
    "typeVersion": "1.1",
    "display": { "label": "Handle Triage Slack Error" },
    "inputs": {
      "script": "const err = $vars.slackTriageNotice1.error;\nreturn { slackMessageId: null, errorMessage: err ? err.message : 'Slack send failed' };"
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the script fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },
  {
    "id": "endEscalation",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "End - Escalation" },
    "inputs": {},
    "outputs": {
      "escalationPath": { "source": "=js:$vars.classify.output.escalationPath" },
      "severity": { "source": "=js:$vars.classify.output.severity" },
      "engineeringNeeded": { "source": "=js:$vars.classify.output.engineeringNeeded" },
      "responseMode": { "source": "=js:$vars.classify.output.responseMode" },
      "caseKey": { "source": "=js:$vars.start.output.correlationId" },
      "slackMessageId": { "source": "=js:($vars.slackEscalationAlert1.output && $vars.slackEscalationAlert1.output.ts) || ($vars.slackEscalationErrorHandler.output && $vars.slackEscalationErrorHandler.output.slackMessageId) || null" }
    }
  },
  {
    "id": "endTriage",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "End - Triage" },
    "inputs": {},
    "outputs": {
      "escalationPath": { "source": "=js:$vars.classify.output.escalationPath" },
      "severity": { "source": "=js:$vars.classify.output.severity" },
      "engineeringNeeded": { "source": "=js:$vars.classify.output.engineeringNeeded" },
      "responseMode": { "source": "=js:$vars.classify.output.responseMode" },
      "caseKey": { "source": "=js:$vars.start.output.correlationId" },
      "slackMessageId": { "source": "=js:($vars.slackTriageNotice1.output && $vars.slackTriageNotice1.output.ts) || ($vars.slackTriageErrorHandler.output && $vars.slackTriageErrorHandler.output.slackMessageId) || null" }
    }
  },
  {
    "id": "start",

